" const mags=rows.map(r=>r[1]),gds=rows.map(r=>r[3]);const mmin=-6,mmax=6;const Y1=v=>T+(1-(Math.max(mmin,Math.min(mmax,v))-mmin)/(mmax-mmin))*(B-T);\n"
" const med=gds.slice().sort((a,b)=>a-b)[gds.length>>1],gmin=med-200,gmax=med+200,Y2=v=>T+(1-(Math.max(gmin,Math.min(gmax,v))-gmin)/(gmax-gmin))*(B-T);\n"
" g.font='10px system-ui';g.strokeStyle=css('--sep');g.fillStyle=css('--tx2');g.lineWidth=1;g.textAlign='center';\n"
" for(let f=0;f<=fm;f+=5000){g.beginPath();g.moveTo(X(f),T);g.lineTo(X(f),B);g.stroke();g.fillText((f/1000)+'k',X(f),H-6);}\n"
" g.textAlign='right';for(let v=mmin;v<=mmax;v+=3){g.beginPath();g.moveTo(L,Y1(v));g.lineTo(R,Y1(v));g.stroke();g.fillText(v+' dB',L-4,Y1(v)+3);}\n"
" g.textAlign='left';g.fillText(Math.round(gmax)+' µs',R+3,T+8);g.fillText(Math.round(med)+' µs',R+3,Y2(med)+3);g.fillText(Math.round(gmin)+' µs',R+3,B);\n"
" g.lineWidth=1.6;g.strokeStyle=css('--ac');g.beginPath();rows.forEach((r,i)=>{i?g.lineTo(X(r[0]),Y1(r[1])):g.moveTo(X(r[0]),Y1(r[1]));});g.stroke();\n"
" g.strokeStyle=css('--warn');g.beginPath();rows.forEach((r,i)=>{i?g.lineTo(X(r[0]),Y2(r[3])):g.moveTo(X(r[0]),Y2(r[3]));});g.stroke();\n"
" g.fillStyle=css('--ac');g.textAlign='left';g.fillText('magnitude (dB, rel. 1 kHz)',L+4,T+9);g.fillStyle=css('--warn');g.fillText('group delay (µs)',L+150,T+9);}\n"
"// ---------------- console ----------------\n"
"const hist=[];let hp=0;\n"
"function log(c,a){const d=$('con');d.insertAdjacentHTML('beforeend','<b>&gt; '+esc(c)+'</b>\\n'+(/^ERR/.test(a)?'<span class=\"e\">':'<span>')+esc(a)+'</span>\\n');d.scrollTop=d.scrollHeight;}\n"
"async function send(){const i=$('cmd'),c=i.value.trim();if(!c)return;hist.push(c);hp=hist.length;i.value='';try{log(c,await cmd(c));}catch(e){log(c,'(no connection)');}}\n"
"$('csend').onclick=send;$('cmd').onkeydown=e=>{if(e.key==='Enter')send();else if(e.key==='ArrowUp'&&hp>0){$('cmd').value=hist[--hp];e.preventDefault();}else if(e.key==='ArrowDown'&&hp<hist.length-1){$('cmd').value=hist[++hp];e.preventDefault();}};\n"
"$('quick').innerHTML=['?S','?E','?M','?D','?G','?A','?B','?J','?V','?T','?P','?O','?R'].map(q=>'<span class=\"chip bit\" style=\"cursor:pointer\" data-q=\"'+q+'\">'+q+'</span>').join('');\n"
"document.querySelectorAll('#quick .chip').forEach(c=>c.onclick=()=>{$('cmd').value=c.dataset.q;send();});\n"
"// ---------------- login ----------------\n"
"$('lg').onclick=async()=>{const r=await fetch('/login',{method:'POST',body:$('pw').value,headers:{'X-Requested-With':'skypluto'}});if(r.ok){authNeeded=false;$('login').style.display='none';poll();}else $('lgm').textContent='Incorrect password.';};\n"
"// ---------------- polling ----------------\n"
"let busy=false,errN=0;\n"
"async function poll(){if(busy)return;busy=true;try{const st=await (await api('/api/state')).json();errN=0;$('err').style.display='none';render(st);fillControl(false);}catch(e){if(!authNeeded&&++errN>1)$('err').style.display='block';}busy=false;}\n"
"async function pollMask(){if(authNeeded||tab!=='ov')return;try{const m=await (await api('/api/mask')).json();Lcur=val(m.L).split(' ')[0]||'';Wcur=val(m.W)||'';Ncur=val(m.N)||'';if(Wcur==='na')Wcur='';if(Ncur==='na')Ncur='';if(Lcur==='na')Lcur='';if(Lcur&&mkH[mkH.length-1]!==Lcur){mkH.push(Lcur);if(mkH.length>24)mkH.shift();}drawMaskBox();}catch(e){}}\n"
"async function pollG(){if(authNeeded||(tab!=='ov'))return;try{const r=await (await api('/api/g')).json();const s=val(r.G);if(!s||s==='na')return;const p=s.split(' ').filter(t=>!/^q=/.test(t)).map(Number);if(p.length&&!p.some(isNaN)){gv=p;drawDev();}}catch(e){}}\n"
"async function pollTone(){if(authNeeded||tab!=='ms')return;try{const r=await (await api('/api/tone')).json();const s=val(r.A);if(!s||s==='na'){$('tf').textContent='–';$('td').textContent='–';return;}const p=s.split(' ');$('tf').textContent=(+p[0]).toFixed(1)+' Hz';$('td').textContent=(+p[1]).toFixed(3)+' kHz  ('+(20*Math.log10(+p[1]/(0.75*(+S.kdev||100)))).toFixed(1)+' dBFS)';}catch(e){}}\n"
"if(location.hash.length>1){try{const tb=document.querySelector('.tabs button[data-t=\"'+location.hash.slice(1).replace(/[^A-Za-z0-9_-]/g,'')+'\"]');if(tb)tb.click();}catch(e){}}\n"
"setInterval(poll,1000);setInterval(pollMask,1000);setInterval(pollG,250);setInterval(pollTone,400);poll();pollMask();\n"
"document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});\n"
"</script></body></html>\n"
"\n";
static const unsigned WEB_INDEX_LEN = sizeof(WEB_INDEX) - 1;
